INSERT INTO `chatmessage` VALUES (175,23,'user','2026-09-14 18:41:56.334','สวัสดี'),(176,23,'assistant','2026-09-14 18:42:08.486','สวัสดีครับ  ผมคือ FitAI Trainer ตอนนี้ผมมีข้อมูลของคุณแล้ว BMI ของคุณคือ 25.1 (Overweight) มีอะไรให้ผมช่วยเกี่ยวกับการออกกำลังกายไหมครับ'),(177,24,'user','2026-09-15 05:16:52.385','สวัสดี'),(178,24,'assistant','2026-09-15 05:17:04.516','สวัสดีครับ  ผมคือ FitAI Trainer ตอนนี้ผมมีข้อมูลของคุณแล้ว BMI ของคุณคือ 25.1 (Overweight) มีอะไรให้ผมช่วยเกี่ยวกับการออกกำลังกายไหมครับ'),(179,24,'user','2026-09-15 05:17:28.968','แนะนำการออกกำลังกายวันนี้'),(180,24,'assistant','2026-09-15 05:17:29.039','ตารางการออกกำลังกายสำหรับวันนี้ (**ช่วงบน**):\n\n**ท่าในตารางที่ต้องออกสำหรับวันนี้:**\n1. **Incline Push-up** (2 เซ็ต · 10–12 ครั้ง)  ▶️ [วิดีโอสอน: Incline Push-up - ???????????????????????????](https://youtu.be/cfns5VDVVvk)\n2. **Decline Push-up** (2 เซ็ต · 10–12 ครั้ง)  ▶️ [วิดีโอสอน: Decline Push-up - ???????????????????????????](https://youtu.be/KhpYYEyfF1c)\n3. **Superman** (2 เซ็ต · 10–12 ครั้ง)  ▶️ [วิดีโอสอน: Supermans - ???????????????????????????](https://youtu.be/vHlVow3pteg)\n4. **Wall Push Up** (2 เซ็ต · 10–12 ครั้ง)  ▶️ [วิดีโอสอน: Wall Push Up - วิดีโอสอน](https://youtu.be/a6YHbXD2XlU)\n5. **Bodyweight Row** (2 เซ็ต · 10–12 ครั้ง)  ▶️ [วิดีโอสอน: Bodyweight Row - วิดีโอสอน](https://youtu.be/rloXYB8M3vU)\n\nตารางออกกำลังกายทางด้านขวาได้รับการอัปเดตตรงตามรายการนี้เรียบร้อยแล้วครับ สามารถคลิกดูคลิปวิดีโอสาธิตแต่ละท่าจาก YouTube ด้านล่างเพื่อฝึกฟอร์มที่ถูกต้องได้เลยครับ 🎯'),(181,24,'user','2026-09-15 05:17:33.211','แนะนำการออกกำลังกายวันนี้'),(182,24,'assistant','2026-09-15 05:17:33.248','ตารางการออกกำลังกายสำหรับวันนี้ (**ช่วงบน**):\n\n**ท่าในตารางที่ต้องออกสำหรับวันนี้:**\n1. **Incline Push-up** (2 เซ็ต · 10–12 ครั้ง)  ▶️ [วิดีโอสอน: Incline Push-up - ???????????????????????????](https://youtu.be/cfns5VDVVvk)\n2. **Decline Push-up** (2 เซ็ต · 10–12 ครั้ง)  ▶️ [วิดีโอสอน: Decline Push-up - ???????????????????????????](https://youtu.be/KhpYY